diff --git a/src/views/tourStops.ts b/src/views/tourStops.ts
index 62d29c1..61cb040 100644
--- a/src/views/tourStops.ts
+++ b/src/views/tourStops.ts
@@ -10,11 +10,12 @@ import { hrRoadY } from '../bridges/han-tunnel/profile';
    Hầm sông Hàn: immerse — chạy mô phỏng dìm đốt hầm; cutaway — bật mặt cắt địa chất; interior — luôn hiện nội thất hầm. */
 export interface TourStop { pos: Vec3; target: Vec3; swing?: boolean; immerse?: boolean; cutaway?: boolean; interior?: boolean }

-/* Cầu Rồng */
+/* Cầu Rồng. Điểm "Trên mặt cầu" đặt ở làn phía Bắc (z < 0) như điểm "Đuôi rồng" trước nó: bản gốc đặt z = +11,5 nên đoạn bay
+   cắt ngang dải phân cách ở x ≈ −282, y ≈ 9,9 — xuyên thân rồng (đỉnh thân ở đó ≈ 12,4 m), `test:tour` báo chạm mô hình */
 export const DRAGON_TOUR: TourStop[] = [
   { pos: [-430, 330, 560], target: [0, 12, 0] },
   { pos: [-410, 22, -48], target: [-345, 11, 0] },
-  { pos: [-228, 11.4, 11.5], target: [-60, 15, 2] },
+  { pos: [-228, 11.4, -11.5], target: [-60, 15, -2] },
   { pos: [-45, 22, -80], target: [0, 30, 0] },
   { pos: [60, 3.5, -145], target: [10, 16, 0] },
   { pos: [392, 26, 40], target: [328, 16, 0] },
/* minY: đường bay được phép xuống dưới mặt nước (mặc định 3 m); loop: false — đường bay mở, đi một lần rồi trả điều khiển (mặc định khép kín, lặp);
   segMax: trần thời lượng một đoạn bay, s (mặc định 16) */
export interface TourDef { view: string; key: string; stops: TourStop[]; minY?: number; loop?: boolean; segMax?: number }

/* Cầu Rồng. Điểm "Trên mặt cầu" đặt ở làn phía Bắc (z < 0) như điểm "Đuôi rồng" trước nó: bản gốc đặt z = +11,5 nên đoạn bay
   cắt ngang dải phân cách ở x ≈ −282, y ≈ 9,9 — xuyên thân rồng (đỉnh thân ở đó ≈ 12,4 m), `test:tour` báo chạm mô hình */
export const DRAGON_TOUR: TourStop[] = [
  { pos: [-430, 330, 560], target: [0, 12, 0] },
  { pos: [-410, 22, -48], target: [-345, 11, 0] },
  { pos: [-228, 11.4, -11.5], target: [-60, 15, -2] },
  { pos: [-45, 22, -80], target: [0, 30, 0] },
  { pos: [60, 3.5, -145], target: [10, 16, 0] },
  { pos: [392, 26, 40], target: [328, 16, 0] },
  { pos: [260, 95, 1700], target: [-110, 70, 1300] },
  { pos: [-150, 70, -430], target: [20, 14, 0] }
];
/* Cầu Trần Thị Lý: toàn cảnh → tháp nghiêng → gối cầu → bờ Đông → mặt phẳng dây trước → dây xoắn → cầu Nguyễn Văn Trỗi,
   sắp sao cho đường bay không xuyên qua mặt cầu hay thân tháp */
export const TTL_TOUR: TourStop[] = [
  { pos: [330, 120, 1740], target: [-70, 55, 1300] },
  { pos: [-40, 26, 1640], target: [-145, 72, 1300] },
  { pos: [-104, 4.2, 1327], target: [-127, 2.5, 1300] },
  { pos: [232, 9, 1440], target: [-80, 50, 1300] },        // trên mặt nước sát bờ Đông, tránh hàng cây ven kè
  { pos: [70, 17.5, 1309], target: [-140, 60, 1300] },     // cao hơn nóc xe buýt
  { pos: [-176, 17.0, 1306], target: [-150, 95, 1301] },   // lệch tim cầu 6 m để đường bay không xuyên thân tháp
  { pos: [60, 18, 1180], target: [-40, 8, 1235] }
import * as THREE from 'three';
import { MAT } from '../../core/materials';
import { shared } from '../../core/shared';

/* Đèn LED trên thân rồng: sóng sáng chạy dọc thân, đổi màu vàng ấm ↔ xanh lam */
function patchDragonGlow(mat: THREE.Material, strength: number) {
  mat.customProgramCacheKey = () => 'glow' + strength;
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uTime = shared.uTime; sh.uniforms.uNight = shared.uNight;
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nvarying float vGX;')
      .replace('#include <fog_vertex>', `#include <fog_vertex>
        { vec4 gp = vec4(transformed, 1.0);
        #ifdef USE_INSTANCING
          gp = instanceMatrix * gp;
        #endif
          vGX = (modelMatrix * gp).x; }`);
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\nvarying float vGX; uniform float uTime; uniform float uNight;')
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        { float k = 0.5 + 0.5 * sin(uTime * 0.6 + vGX * 0.012);
          float w = 0.5 + 0.5 * sin(vGX * 0.07 - uTime * 2.6);
          float pulse = 0.35 + 0.65 * w * w;
          vec3 c = mix(vec3(1.0, 0.64, 0.2), vec3(0.22, 0.48, 1.0), k);
          totalEmissiveRadiance += c * pulse * uNight * ${strength.toFixed(2)}; }`);
  };
}
patchDragonGlow(MAT.gold, 0.7);
patchDragonGlow(MAT.scale, 0.9);
64:| `npm run test:tour` | đạt: dragon 8, tp 7, ttl 7, sh 6, hr 8, all 13, **sw 6**, storm 8 |
91:| `npm run test:tour` | đạt: dragon 8, tp 7, ttl 7, sh 6, hr 8, **all 13** (camera thấp nhất 24 m, cầu sông Hàn tự quay ở điểm 8, hết hành trình → orbit), storm 8 |
105:| `npm run test:tour` | đạt: dragon 8, tp 7, ttl 7, sh 6, hr 8 điểm dừng |
216:dragon 8 điểm dừng, camera thấp nhất 3 m → đạt
226:Bảng 2026-10-20 cho bản gốc (đối chiếu): dragon ghi LỖI do một điểm chạm ở (−282,2; 9,9; −2,2) đã có sẵn trong bản gốc. Từ GĐ4 (D-011), điểm 3 Tour Cầu Rồng đã đổi sang làn Bắc, nên dragon đạt ở bản Vite. `test:tour -- tests/original` vì vậy báo khác bản gốc ở dragon có chủ đích.

