  g.setAttribute('aColor', new THREE.BufferAttribute(sys.col, 3).setUsage(THREE.DynamicDrawUsage));
  g.setAttribute('aSize', new THREE.BufferAttribute(sys.size, 1).setUsage(THREE.DynamicDrawUsage));
