      const sp = mist ? 8 + rand() * 5 : 26 + rand() * 6;
      s.pos[i * 3] = mouthW.x; s.pos[i * 3 + 1] = mouthW.y; s.pos[i * 3 + 2] = mouthW.z;
      s.vel[i * 3] = fwd.x * sp + (rand() - 0.5) * 2.5; s.vel[i * 3 + 1] = sp * 0.42 + (rand() - 0.5) * 2.5; s.vel[i * 3 + 2] = (rand() - 0.5) * (mist ? 6 : 2.5);
