    for (let a = 0; a < 3; a++) waterJet.pos[i * 3 + a] += waterJet.vel[i * 3 + a] * dt;
    waterJet.col[i * 3] = mist ? 0.9 : 0.62; waterJet.col[i * 3 + 1] = mist ? 0.95 : 0.84; waterJet.col[i * 3 + 2] = 1.0;
